        return s.count('0'), s.count('1')

    def check_balance(s, k):
        for i in range(n - k + 1):
            sub = s[i:i+k]
            zeros, ones = count_01(sub)
            if zeros != ones:
                return False
        return True

    def replace_question_marks(s, k):
        question_count = s.count('?')
        if question_count == 0:
            return check_balance(s, k)

        # Try replacing '?' with '0' and '1'
        s0 = s.replace('?', '0')
        s1 = s.replace('?', '1')

        return check_balance(s0, k) or check_balance(s1, k)

    return replace_question_marks(s, k)

